/// <summary>
/// MPJ_19351_FTI Document date, default to todays date  DCP 02/02/2022
/// </summary>
[ExtensionOf(tableStr(CustInvoiceTable))]
final class METCustInvoiceTable_Table_Extension
{
}

Method.Source:
    /// <summary>
    /// Initialise DocumentDate
    /// </summary>
    /// <param name = "custTable">CustTable buffer</param>
    public void initFromCustTable(CustTable custTable)
    {
        next initFromCustTable(custTable);

        this.DocumentDate = CustInvoiceTable::getDefaultInvoiceDate();
        this.CustBankAccountId = null; //MPJ_19880

    }

    /// <summary>
    /// Display the Description from the first line of FTI
    /// </summary>
    /// <returns>Description from first line of FTI</returns>
    display TransactionTextLarge METLineDescription()
    {
        TransactionTextLarge    description;
        CustInvoiceLine         custInvoiceLine;

        while select firstonly description 
            from custInvoiceLine
            where custInvoiceLine.ParentRecId == this.recId
        {
            description = custInvoiceLine.Description;
        }
        return description;
    }

    /// <summary>
    /// Retrieves the date the Customer Transaction was closed
    /// </summary>
    /// <returns>Date the Customer Transaction was closed </returns>
    display METClosedDate METDisplayClosedDate()
    {
        METClosedDate   closedDate;
        CustInvoiceJour custInvoiceJour;
        CustTrans       custTrans;

        while select firstonly RecId from custInvoiceJour
            where   custInvoiceJour.InvoiceId           == this.InvoiceId
            &&      custInvoiceJour.InvoiceDate         == this.InvoiceDate
            &&      custInvoiceJour.NumberSequenceGroup == this.NumberSequenceGroup
            &&      custInvoiceJour.SalesId             == '' //no sales id on FTI

            join    Closed from custTrans
            where   custTrans.Invoice           == custInvoiceJour.InvoiceId
            &&      custTrans.AccountNum        == custInvoiceJour.InvoiceAccount
            &&      custTrans.TransDate         == custInvoiceJour.InvoiceDate
            &&      custTrans.Voucher           == custInvoiceJour.LedgerVoucher
            &&      custTrans.Closed
        {
            closedDate = custTrans.Closed;
        }
        
        return closedDate;
    }

/// <summary>
/// Sets the <c>CustInvoiceTable</c> table fields based on the <c>CustRecurrenceInvoiceDefaultType</c>
/// field.
/// </summary>
/// <param name="_custInvoiceTemplate">
/// An instance of a <c>CustInvoiceTemplate</c> table buffer.
/// </param>
/// <param name="_custTable">
/// An instance of a <c>CustTable</c> table buffer.
/// </param>
/// <param name="_custRecurrenceInvoiceDefaultType">
/// The default type for customer recurrence invoice setup.
/// </param>
/// <param name="_generationDate">
/// The generation date of recurrence invoice.
/// </param>
public void initFromCustInvoiceTemplate(
    CustInvoiceTemplate _custInvoiceTemplate,
    CustTable _custTable,
    CustRecurrenceInvoiceDefaultType _custRecurrenceInvoiceDefaultType,
    TransDate _generationDate)
{
    next initFromCustInvoiceTemplate(_custInvoiceTemplate,
            _custTable,
            _custRecurrenceInvoiceDefaultType,
            _generationDate);
    
    this.CustBankAccountId = null; //MPJ_19880
}

    /// <summary>
    /// Validate the free text invoice.
    /// </summary>
    /// <returns>Return true if success; else false.</returns>
    /// Added for CFR4 bulk approval AR invoice
    boolean validateWrite()
    {
        boolean ret = next validateWrite();

        if (ret && this.METRecipientEmail && !SysEmailDistributor::validateEmail(this.METRecipientEmail))
        {
            ret = checkFailed("@MET:METFTIReceiptMailAddressValid");
        }

        return ret;
    }

    /// <summary>
    /// Retrieves the user who submitted the invoice to workflow.
    /// </summary>
    /// <returns>
    /// A string that contains the user who submitted the invoice to workflow.
    /// </returns>
    /// Added for CFR4 bulk approval AR invoice
    [SysClientCacheDataMethod(true)]
    public display UserIdStr getSubmittedByUserName()
    {
        UserInfo                      userInfo;
        WorkflowTrackingStatusTable   workflowTrackingStatusTable;

        select firstonly originator from workflowTrackingStatusTable
            order by RecId desc
            where workflowTrackingStatusTable.ContextRecId   == this.RecId   &&
                  workflowTrackingStatusTable.ContextTableId == this.TableId
                join name from userInfo
                    where userInfo.Id == workflowTrackingStatusTable.Originator;

        return (userInfo.name) ? userInfo.name : '';
    }

    /// <summary>
    /// Gets the name of the user who approved the workflow.
    /// </summary>
    /// <returns>The name of the user who approved the workflow.</returns>
    /// Added for CFR4 bulk approval AR invoice
    [SysClientCacheDataMethod(true)]
    public display UserIdStr getApprovedByUserName()
    {
        WorkflowTrackingStatusTable workflowTrackingStatusTable;
        WorkflowTrackingTable       workflowTrackingTable;
        UserInfo                    userInfo;

        select firstonly user from workflowTrackingTable
            order by CreatedDateTime desc, RecId desc
            join name from userInfo
            where userInfo.Id == workflowTrackingTable.User
                exists join workflowTrackingStatusTable
                where  workflowTrackingTable.WorkflowTrackingStatusTable == workflowTrackingStatusTable.RecId
                    && workflowTrackingTable.TrackingContext == WorkflowTrackingContext::WorkItem
                    && workflowTrackingTable.TrackingType == WorkflowTrackingType::Approval
                    && workflowTrackingStatusTable.ContextRecId == this.RecId
                    && workflowTrackingStatusTable.ContextTableId == this.TableId;

        return (userInfo.name) ? userInfo.name : '';
    }

    /// <summary>
    /// Initialize the workflow approval status and state based on condition.
    /// </summary>
    /// Added for CFR4 bulk approval AR invoice
    protected void initializeWorkflowApprovalStatusAndState()
    {
        next initializeWorkflowApprovalStatusAndState();

        if (METBulkWFFreeTextInvoiceHelper::checkUserIdIsPartofExclusionlist())
        {
            this.WorkflowApprovalStatus = CustFreeInvoiceWFApprovalStatus::Approved;
            this.WorkflowApprovalState  = CustFreeInvoiceWFApprovalState::WorkflowCompleted;
        }
    }

    /// <summary>
    /// Update the free text invoice table.
    /// </summary>
    /// Added for CFR4 bulk approval AR invoice
    void update()
    {
        if (METBulkWFFreeTextInvoiceHelper::checkUserIdIsPartofExclusionlist() && 
            this.WorkflowApprovalStatus != CustFreeInvoiceWFApprovalStatus::Approved)
        {
            this.WorkflowApprovalStatus = CustFreeInvoiceWFApprovalStatus::Approved;
            this.WorkflowApprovalState  = CustFreeInvoiceWFApprovalState::WorkflowCompleted;
        }

        next update();
    }

    /// <summary>
    /// MPJ_24809 Returns Claims
    /// Finds the specified record in the <c>CustInvoiceTable</c> table.
    /// </summary>
    /// <param name="_metClaimId">
    /// The METClaimId of the <c>CustInvoiceTable</c> record to find.
    /// </param>
    /// <param name="_update">
    /// A Boolean value that indicates whether to read the record for update; optional.
    /// </param>
    /// <returns>
    /// A record in the <c>CustInvoiceTable</c> table; otherwise, an empty record.
    /// </returns>
    public static CustInvoiceTable findMETClaimId(
        METClaimId      _metClaimId,
        boolean     _update = false)
    {
        CustInvoiceTable  metCustInvoiceTableStd;

        metCustInvoiceTableStd.selectForUpdate(_update);

        if (_metClaimId)
        {
            select firstonly metCustInvoiceTableStd
                where metCustInvoiceTableStd.METClaimId == _metClaimId;
        }

        return metCustInvoiceTableStd;
    }

    /// <summary>
    /// Check whtehr whether the FTI is getting created through interface.
    /// If not through interface, set 'Return status = Not rreuiqred'.
    /// </summary>
    /// <remarks>
    /// Cretaed for FSD-CB210
    /// </remarks>
    void insert()
    {

        if (!this.METClaimId)
        {
            this.METReturnStatus = METReturnStatus::NotRequired;
        }

        //Task182820-CB272_SalesInvoicing-rebates-start
        if (this.TAMRebateTransId)
        {
            this.METVolumetricTierDeal = TAMRebateDeal::find(TAMRebateDateTrans::find(this.TAMRebateTransId).RebateDeal).METVolumetricTierDeal;
        }
        //Task182820-CB272_SalesInvoicing-rebates-end
        
        next insert();
    }

/// <summary>
/// initialize record values
/// </summary>
void initValue()
{
    next initValue();
    this.METReturnStatus = METReturnStatus::NotRequired; //287591 defaulting
}
